<template><div class="container">  <div class="Index">    <Row>      <Menu mode="horizontal" :theme="theme1" :active-name="activeName" @on-select="select">        <Col span="22">          <MenuItem name="0"></MenuItem>          <MenuItem name="home">首页</MenuItem>          <MenuItem name="openSourceBooks">开源书籍</MenuItem>          <MenuItem name="openSourceProject">开源项目</MenuItem>          <MenuItem name="links">友链</MenuItem>          <MenuItem name="about">关于</MenuItem>        </Col>        <Col span="2" style="float: right">          <Button v-if="loginBefore" @click="gotoLogin">请登录</Button>          <Dropdown v-if="loginAfter" @on-click="dropdownMethod">            <Button type="primary">              {{username}}              <Icon type="logo-octocat" size="24"/>            </Button>            <DropdownMenu slot="list" align="center">              <DropdownItem name="userInfo">个人主页</DropdownItem>              <DropdownItem name="releaseBlog">发布博客</DropdownItem>              <DropdownItem name="blogManagement">博客管理</DropdownItem>              <DropdownItem name="logout">退出登录</DropdownItem>            </DropdownMenu>          </Dropdown>        </Col>      </Menu>    </Row>    <Row>      <Col span="24">        <div class="content">          <router-view/>        </div>      </Col>    </Row>  </div></div></template><script>export default {  name: 'Index',  data() {    return {      theme1: 'light',      activeName: 'home',      loginBefore: true,      loginAfter: false,      username: ''    }  },  created() {    this.checkLoginStatus()    this.setActiveMenu()  },  watch: {    '$route': function() {      this.setActiveMenu()    }  },  methods: {    checkLoginStatus() {      const token = localStorage.getItem('token')      const username = localStorage.getItem('username')      if (token && username) {        this.loginBefore = false        this.loginAfter = true        this.username = username      } else {        this.loginBefore = true        this.loginAfter = false      }    },    setActiveMenu() {      const path = this.$route.path      switch(path) {        case '/':        case '/home':          this.activeName = 'home'          break        case '/openSourceBooks':          this.activeName = 'openSourceBooks'          break        case '/openSourceProject':          this.activeName = 'openSourceProject'          break        case '/links':          this.activeName = 'links'          break        case '/about':          this.activeName = 'about'          break        default:          this.activeName = 'home'      }    },    select(name) {      this.activeName = name      switch(name) {        case 'home':          this.$router.push('/home')          break        case 'openSourceBooks':          this.$router.push('/openSourceBooks')          break        case 'openSourceProject':          this.$router.push('/openSourceProject')          break        case 'links':          this.$router.push('/links')          break        case 'about':          this.$router.push('/about')          break      }    },    gotoLogin() {      this.$router.push('/login')    },    dropdownMethod(name) {      switch(name) {        case 'userInfo':          this.$router.push('/userInfo')          break        case 'releaseBlog':          this.$router.push('/releaseBlog')          break        case 'blogManagement':          this.$router.push('/blogManagement')          break        case 'logout':          localStorage.removeItem('token')          localStorage.removeItem('username')          localStorage.removeItem('authorId')          this.loginBefore = true          this.loginAfter = false          this.$router.push('/home')          this.$Message.success('退出登录成功')          break      }    }  }}</script><style scoped>.Index {  font-family: 'Avenir', Helvetica, Arial, sans-serif;  -webkit-font-smoothing: antialiased;  -moz-osx-font-smoothing: grayscale;  color: #2c3e50;}.content {  margin-top: 20px;  min-height: 600px;}.Menu {  background-color: #f8f9fa;  border-bottom: 1px solid #e9ecef;}.Menu .ivu-menu-item {  padding: 0 20px;  line-height: 60px;  font-size: 16px;}.Menu .ivu-menu-item-active {  color: #409eff;  border-bottom: 2px solid #409eff;}.Menu .ivu-menu-item:hover {  color: #66b1ff;}.Menu .ivu-col:last-child {  text-align: right;}.Menu .ivu-btn {  margin-top: 15px;}.Menu .ivu-dropdown {  margin-top: 15px;}/* 响应式设计 */@media (max-width: 768px) {  .Menu .ivu-col {    width: 100% !important;  }    .Menu .ivu-col:first-child {    margin-bottom: 10px;  }    .Menu .ivu-col:last-child {    text-align: center;  }    .Menu .ivu-menu-item {    padding: 0 10px;    font-size: 14px;  }    .Menu .ivu-btn, .Menu .ivu-dropdown {    margin-top: 10px;  }    .content {    margin-top: 10px;    min-height: 400px;  }}@media (max-width: 480px) {  .Menu .ivu-menu-item {    padding: 0 5px;    font-size: 12px;  }    .Menu .ivu-btn {    padding: 4px 8px;    font-size: 12px;  }}</style>